-- Worker-local physical-byte retention for presentation preparation: a bounded
-- read-through catalog sits below logical decoding and serves repeat reads of
-- already-fetched generated bytes without a second native read. Synthetic
-- backends only; no ROM bytes and no graphics objects. Every test below fails
-- while the worker-private catalog module is absent, naming the missing
-- retention behavior instead of failing the suite load.

local Assert = require("tests.support.Assert")
local CacheEnvelope = require("tests.support.CacheEnvelope")
local CacheFs = require("libs.storage.src.CacheFs")
local FakeCache = require("tests.support.FakeCache")
local PngWriter = require("tests.support.PngEncoder")

local T = {}

local haveCatalog, CatalogModule = pcall(require, "libs.hgss.src.presentation.CompressedAssetCatalog")

---@return table the worker-private physical-byte catalog under test
local function catalogModule()
  Assert.isTrue(
    haveCatalog and type(CatalogModule) == "table",
    "the worker-local compressed source catalog is missing: repeat preparation "
      .. "of generated image, mesh, and sample bytes must reuse retained physical "
      .. "bytes instead of rereading the native file"
  )
  return CatalogModule --[[@as table]]
end

---@return table backend, table<string, integer> nativeReads
local function codecBackend()
  local backend = FakeCache.new()
  CacheEnvelope.attachHostCodecs(backend)
  ---@type table<string, integer>
  local nativeReads = {}
  local innerRead = backend.read
  function backend.read(self, path)
    nativeReads[path] = (nativeReads[path] or 0) + 1
    return innerRead(self, path)
  end
  return backend, nativeReads
end

---@param backend table counting fake backend under test
---@param versionId string version namespace the catalog serves
---@param byteLimit integer fixed resident-byte ceiling
---@return table catalog
local function newCatalog(backend, versionId, byteLimit)
  local nativeRead = backend.read
  return catalogModule().new(function(fullPath)
    return nativeRead(backend, fullPath)
  end, versionId, byteLimit)
end

-- Mirrors the worker wiring: capture the native read once, then serve the
-- versioned cache through the catalog-backed read.
---@param backend table counting fake backend under test
---@param versionId string version namespace the catalog serves
---@param byteLimit integer fixed resident-byte ceiling
---@return table catalog, table cache
local function wrapBackendWithCatalog(backend, versionId, byteLimit)
  local catalog = newCatalog(backend, versionId, byteLimit)
  backend.read = function(_, fullPath)
    return catalog:read(fullPath)
  end
  return catalog, CacheFs.forVersion(versionId, backend)
end

-- A second preparation of the same generated image after its decoded result
-- was released must reuse the retained physical bytes: one native PNG read
-- serves two identical logical reads while the entry stays resident.
function T.second_read_of_a_retained_image_serves_ram_without_a_second_native_read()
  local backend, nativeReads = codecBackend()
  local versionId = "heartgold"
  local logicalPath = "assets/generated/textures/a.png"
  local fullPath = versionId .. "/" .. logicalPath
  local png = PngWriter.encode(2, 2, string.char(255, 0, 0, 255):rep(4))
  CacheFs.forVersion(versionId, backend):write(logicalPath, png)
  Assert.equal(backend.files[fullPath], png, "portable image bytes stay native on disk")

  local catalog, cache = wrapBackendWithCatalog(backend, versionId, 64 * 1024 * 1024)
  local first = cache:read(logicalPath)
  local second = cache:read(logicalPath)
  Assert.equal(first, png, "the first logical read is exact")
  Assert.equal(second, png, "the retained physical bytes decode identically")
  Assert.equal(nativeReads[fullPath], 1, "the second preparation must not reread the native file")

  local stats = catalog:stats()
  Assert.keySet(stats, "entries,evictions,hits,reads,retainedBytes")
  Assert.equal(stats.entries, 1, "one physical entry is resident")
  Assert.equal(stats.hits, 1, "the second read is a catalog hit")
  Assert.equal(stats.evictions, 0, "nothing was evicted")
  Assert.equal(stats.retainedBytes, #png, "retained bytes count the stored physical image")
end

-- The byte budget counts stored physical bytes and retires the oldest entry
-- first: a hot entry survives an overflowing insert, the evicted path reads
-- transparently once more, empty reads are preserved, and a single blob
-- larger than the ceiling bypasses retention without disturbing the ledger.
function T.bounded_catalog_evicts_the_least_recently_used_entry()
  local backend, nativeReads = codecBackend()
  local versionId = "heartgold"
  local function logicalPath(name)
    return "data/generated/audio/" .. name .. ".pcm16le"
  end
  local payloadA = string.rep("ab", 150)
  local payloadB = string.rep("cd", 150)
  local payloadC = string.rep("ef", 150)
  local payloadD = string.rep("gh", 350)
  local writer = CacheFs.forVersion(versionId, backend)
  writer:write(logicalPath("a"), payloadA)
  writer:write(logicalPath("b"), payloadB)
  writer:write(logicalPath("c"), payloadC)
  writer:write(logicalPath("d"), payloadD)
  writer:write(logicalPath("e"), "")
  local fullA = versionId .. "/" .. logicalPath("a")
  local fullB = versionId .. "/" .. logicalPath("b")
  local fullD = versionId .. "/" .. logicalPath("d")
  local fullE = versionId .. "/" .. logicalPath("e")
  Assert.equal(backend.files[fullA], payloadA, "small payloads stay raw so sizes are exact")
  Assert.equal(#payloadD, 700, "the oversized fixture must exceed the test ceiling")

  local catalog, cache = wrapBackendWithCatalog(backend, versionId, 600)
  Assert.equal(cache:read(logicalPath("a")), payloadA)
  Assert.equal(cache:read(logicalPath("b")), payloadB)
  Assert.equal(cache:read(logicalPath("a")), payloadA, "a hot read moves the entry to newest")
  Assert.equal(cache:read(logicalPath("c")), payloadC, "the overflowing insert evicts the oldest entry")
  local stats = catalog:stats()
  Assert.isTrue(stats.retainedBytes <= 600, "residency never exceeds the ceiling")
  Assert.isTrue(stats.evictions >= 1, "the overflow retired at least one entry")
  Assert.equal(cache:read(logicalPath("a")), payloadA, "the hot entry survives the eviction")
  Assert.equal(nativeReads[fullA], 1, "the surviving entry serves RAM without rereading")
  Assert.equal(cache:read(logicalPath("b")), payloadB, "the evicted entry reads transparently again")
  Assert.equal(nativeReads[fullB], 2, "the evicted path rereads its native file exactly once more")

  Assert.equal(cache:read(logicalPath("e")), "", "empty successful reads preserve their bytes")
  Assert.equal(cache:read(logicalPath("e")), "")
  Assert.equal(nativeReads[fullE], 1, "empty bytes are retained, not refetched")

  local entriesBefore = catalog:stats().entries
  local retainedBefore = catalog:stats().retainedBytes
  Assert.equal(cache:read(logicalPath("d")), payloadD, "an oversized blob still reads through")
  Assert.equal(cache:read(logicalPath("d")), payloadD)
  Assert.equal(nativeReads[fullD], 2, "an oversized blob bypasses retention entirely")
  Assert.equal(catalog:stats().entries, entriesBefore, "bypassed bytes never enter the ledger")
  Assert.equal(catalog:stats().retainedBytes, retainedBefore, "bypassed bytes never count toward the budget")
end

-- Wrapped mesh and sample envelopes decode to exact logical bytes through a
-- retained physical entry, the budget counts envelope bytes rather than
-- inflated output, and a damaged envelope still fails as a decode error on
-- every attempt instead of succeeding from RAM.
function T.wrapped_envelopes_decode_exactly_from_retained_physical_bytes()
  local backend, nativeReads = codecBackend()
  local versionId = "soulsilver"
  local meshLogical = "data/generated/geometry/chunk.g4mesh"
  local pcmLogical = "data/generated/audio/theme.pcm16le"
  local meshPayload = string.rep("vertex-block-0123456789;", 300)
  local pcmPayload = string.rep("\0\1\2\3sample;", 512)
  local writer = CacheFs.forVersion(versionId, backend)
  writer:write(meshLogical, meshPayload)
  writer:write(pcmLogical, pcmPayload)
  local meshFull = versionId .. "/" .. meshLogical
  local pcmFull = versionId .. "/" .. pcmLogical
  local physicalMesh = backend.files[meshFull]
  local physicalPcm = backend.files[pcmFull]
  Assert.isTrue(
    type(physicalMesh) == "string" and CacheEnvelope.isWrapped(physicalMesh),
    "the mesh fixture must land wrapped"
  )
  Assert.isTrue(
    type(physicalPcm) == "string" and CacheEnvelope.isWrapped(physicalPcm),
    "the sample fixture must land wrapped"
  )
  Assert.isTrue(#physicalMesh < #meshPayload, "the wrapped mesh saves space")
  Assert.isTrue(#physicalPcm < #pcmPayload, "the wrapped sample saves space")

  local catalog, cache = wrapBackendWithCatalog(backend, versionId, 64 * 1024 * 1024)
  Assert.equal(cache:read(meshLogical), meshPayload)
  Assert.equal(cache:read(meshLogical), meshPayload, "the retained envelope decodes identically")
  Assert.equal(cache:read(pcmLogical), pcmPayload)
  Assert.equal(cache:read(pcmLogical), pcmPayload, "mixed families share the same catalog")
  Assert.equal(nativeReads[meshFull], 1, "the mesh envelope is fetched once while resident")
  Assert.equal(nativeReads[pcmFull], 1, "the sample envelope is fetched once while resident")
  local stats = catalog:stats()
  Assert.equal(
    stats.retainedBytes,
    #physicalMesh + #physicalPcm,
    "the budget counts stored envelope bytes, not inflated logical bytes"
  )
  Assert.isTrue(
    stats.retainedBytes < #meshPayload + #pcmPayload,
    "resident bytes stay compressed while logical reads stay exact"
  )

  local corruptLogical = "data/generated/geometry/broken.g4mesh"
  local corruptFull = versionId .. "/" .. corruptLogical
  backend:write(corruptFull, "PDC1" .. string.char(9) .. "damaged-payload")
  local ok, err = pcall(function()
    return cache:read(corruptLogical)
  end)
  Assert.isFalse(ok, "a damaged envelope must fail instead of returning bytes")
  Assert.isTrue(
    type(err) == "table" and err.code == CacheEnvelope.DECODE_FAILED,
    "the failure names decoding: " .. corruptLogical
  )
  local retryOk, retryErr = pcall(function()
    return cache:read(corruptLogical)
  end)
  Assert.isFalse(retryOk, "a damaged envelope fails on retry, never succeeding from RAM")
  Assert.isTrue(
    type(retryErr) == "table" and retryErr.code == CacheEnvelope.DECODE_FAILED,
    "the retry names decoding: " .. corruptLogical
  )
  Assert.equal(nativeReads[corruptFull], 1, "the corrupt physical bytes hit RAM while decoding still rejects them")
end

-- A missing derived file is never negatively cached: the original backend
-- pair is preserved, every miss reaches the backend, and a later published
-- file reads successfully and is then retained.
function T.missing_files_are_never_retained_and_later_publication_is_visible()
  local backend, nativeReads = codecBackend()
  local versionId = "heartgold"
  local logicalPath = "data/generated/geometry/future.g4mesh"
  local fullPath = versionId .. "/" .. logicalPath
  local catalog = newCatalog(backend, versionId, 64 * 1024 * 1024)

  local first, firstErr = catalog:read(fullPath)
  Assert.isNil(first, "a missing file stays missing")
  local second, secondErr = catalog:read(fullPath)
  Assert.isNil(second, "a missing file is never negatively cached")
  Assert.equal(firstErr, secondErr, "the original backend pair is preserved across misses")
  Assert.equal(nativeReads[fullPath], 2, "each miss reaches the backend so later publication is visible")
  Assert.equal(catalog:stats().retainedBytes, 0, "misses retain nothing")
  Assert.equal(catalog:stats().entries, 0, "misses create no entries")

  local failingReads = 0
  local failingBackend = {
    read = function(_, _)
      failingReads = failingReads + 1
      return nil, "injected read failure"
    end,
  }
  local failingCatalog = catalogModule().new(function(path)
    return failingBackend.read(failingBackend, path)
  end, versionId, 1024)
  local failed, failedErr = failingCatalog:read(fullPath)
  Assert.isNil(failed, "a failed read stays a failure")
  Assert.equal(failedErr, "injected read failure", "the backend error survives the miss")
  Assert.isNil(failingCatalog:read(fullPath))
  Assert.equal(failingReads, 2, "a failed read is never negatively cached")

  local payload = string.rep("published-geometry;", 40)
  CacheFs.forVersion(versionId, backend):write(logicalPath, payload)
  Assert.equal(catalog:read(fullPath), payload, "a later published file reads successfully")
  Assert.equal(catalog:read(fullPath), payload)
  Assert.equal(nativeReads[fullPath], 3, "the published bytes are retained after one fetch")
end

-- Catalogs are worker-local: a fresh worker starts empty, another version
-- never shares retained bytes, and private, staging, and out-of-prefix
-- paths always read through without entering the ledger.
function T.fresh_workers_start_empty_and_private_paths_stay_uncached()
  local backend, nativeReads = codecBackend()
  local payload = string.rep("shared-bytes;", 40)
  local logicalPath = "assets/generated/textures/shared.png"
  CacheFs.forVersion("heartgold", backend):write(logicalPath, payload)
  local fullPath = "heartgold/" .. logicalPath

  local emptyVersionErr = Assert.throws(function()
    catalogModule().new(function(path)
      return backend:read(path)
    end, "", 1024)
  end, "an empty version identity is a programming error")
  Assert.isTrue(
    tostring(emptyVersionErr):find("version", 1, true) ~= nil,
    "the constructor names the bad identity: " .. tostring(emptyVersionErr)
  )

  local catalog = newCatalog(backend, "heartgold", 64 * 1024 * 1024)
  Assert.equal(catalog:read(fullPath), payload)
  Assert.equal(catalog:read(fullPath), payload)
  Assert.equal(nativeReads[fullPath], 1, "the first worker retains its own bytes")

  local fresh = newCatalog(backend, "heartgold", 64 * 1024 * 1024)
  Assert.equal(fresh:stats().entries, 0, "a new worker starts with no entries")
  Assert.equal(fresh:stats().retainedBytes, 0, "a new worker retains no bytes")
  Assert.equal(fresh:read(fullPath), payload)
  Assert.equal(nativeReads[fullPath], 2, "a new worker fetches its own copy")

  local other = newCatalog(backend, "soulsilver", 64 * 1024 * 1024)
  Assert.equal(other:read(fullPath), payload, "out-of-version bytes still read through")
  Assert.equal(other:read(fullPath), payload)
  Assert.equal(nativeReads[fullPath], 4, "another version never shares the first worker's bytes")
  Assert.equal(other:stats().entries, 0, "out-of-version bytes are never retained")

  local privateLogical = "data/generated/_prepared/ticket.bin"
  CacheFs.forVersion("heartgold", backend):write(privateLogical, payload)
  local privateFull = "heartgold/" .. privateLogical
  local entriesBefore = catalog:stats().entries
  Assert.equal(catalog:read(privateFull), payload, "private derivative bytes still read through")
  Assert.equal(catalog:read(privateFull), payload)
  Assert.equal(nativeReads[privateFull], 2, "private derivative paths are never retained")
  Assert.equal(catalog:stats().entries, entriesBefore, "ineligible paths never enter the ledger")

  local stagingFull = "heartgold.__g4next/data/generated/staged.lua"
  backend:write(stagingFull, payload)
  Assert.equal(catalog:read(stagingFull), payload, "staging roots still read through")
  Assert.equal(catalog:read(stagingFull), payload)
  Assert.equal(nativeReads[stagingFull], 2, "staging roots are never retained")
  Assert.equal(catalog:stats().entries, entriesBefore, "staging paths never enter the ledger")

  local siblingFull = "heartgold-evil/assets/generated/textures/shared.png"
  backend:write(siblingFull, payload)
  Assert.equal(catalog:read(siblingFull), payload, "near-prefix paths still read through")
  Assert.equal(catalog:read(siblingFull), payload)
  Assert.equal(nativeReads[siblingFull], 2, "the version prefix requires a slash boundary")
  Assert.equal(catalog:stats().entries, entriesBefore, "near-prefix paths never enter the ledger")
end

return { tests = T }
